1	// PayPal Orders v2 client — a genuine second payment rail alongside Stripe.
2	//
3	// GATING. Exactly the pattern `lib/seo/searchConsole.ts`'s `gscConfigured()` uses:
4	// a pure `paypalConfigured()` reading only env vars, checked BEFORE every server
5	// action and BEFORE the client ever renders a PayPal button. `PAYPAL_CLIENT_ID`,
6	// `PAYPAL_CLIENT_SECRET` and `PAYPAL_WEBHOOK_ID` do not exist in any environment yet
7	// (the owner is creating a PayPal Business account in parallel) — every function
8	// here is inert (returns null / throws a caught, typed error) rather than crashing
9	// when they are absent, so this ships dark and lights up the moment the three env
10	// vars are set. No fake/sandbox fallback credentials are baked in anywhere.
11	//
12	// MONEY MODEL. PayPal is authorized then CAPTURED server-to-server — the same
13	// "never trust the client" posture Stripe gets for free from `checkout.sessions`.
14	// `createPayPalOrder` is called from OUR server action with a price WE computed;
15	// `capturePayPalOrder` is a server-to-server call PayPal itself answers, and only
16	// its answer (not anything the browser reports) is treated as "the money moved".
17	// See lib/actions-payment-providers.ts for how this plugs into the same
18	// reserve → pay → fulfil pipeline every other payment method uses.
19	//
20	// FULFILMENT SEAM. This file never touches provisioning, the database beyond a
21	// `PendingExternalPayment` row, or Stripe. It hands a captured order id + amount
22	// back to the caller, which routes it through `fulfilExternalPayment`
23	// (lib/fulfil-checkout.ts) — the SAME dispatch `fulfilCheckoutSession` uses for
24	// Stripe. See that file for the unification.
25	
26	const SANDBOX_BASE = "https://api-m.sandbox.paypal.com";
27	const LIVE_BASE = "https://api-m.paypal.com";
28	
29	function clientId(): string {
30	  return (process.env.PAYPAL_CLIENT_ID ?? "").trim();
31	}
32	function clientSecret(): string {
33	  return (process.env.PAYPAL_CLIENT_SECRET ?? "").trim();
34	}
35	
36	/** Is PayPal configured in this environment? Gates every UI surface and action. */
37	export function paypalConfigured(): boolean {
38	  return !!clientId() && !!clientSecret();
39	}
40	
41	/**
42	 * Which PayPal environment to call. Defaults to sandbox — a missing/blank
43	 * `PAYPAL_MODE` must never accidentally take real money, so "live" is opt-in only.
44	 */
45	function apiBase(): string {
46	  return (process.env.PAYPAL_MODE ?? "").trim().toLowerCase() === "live" ? LIVE_BASE : SANDBOX_BASE;
47	}
48	
49	/** The publishable-safe client id, for the browser SDK script. "" when unconfigured. */
50	export function paypalClientIdPublic(): string {
51	  return clientId();
52	}
53	
54	type TokenCache = { token: string; expiresAt: number } | null;
55	let tokenCache: TokenCache = null;
56	
57	async function getAccessToken(): Promise<string> {
58	  if (!paypalConfigured()) throw new Error("PayPal is not configured");
59	  const now = Date.now();
60	  if (tokenCache && tokenCache.expiresAt - 30_000 > now) return tokenCache.token;
61	
62	  const basic = Buffer.from(`${clientId()}:${clientSecret()}`).toString("base64");
63	  const res = await fetch(`${apiBase()}/v1/oauth2/token`, {
64	    method: "POST",
65	    headers: {
66	      Authorization: `Basic ${basic}`,
67	      "Content-Type": "application/x-www-form-urlencoded",
68	    },
69	    body: "grant_type=client_credentials",
70	  });
71	  if (!res.ok) {
72	    throw new Error(`PayPal OAuth failed: ${res.status} ${await res.text().catch(() => "")}`);
73	  }
74	  const json = (await res.json()) as { access_token: string; expires_in: number };
75	  tokenCache = { token: json.access_token, expiresAt: now + json.expires_in * 1000 };
76	  return json.access_token;
77	}
78	
79	async function paypalFetch<T>(path: string, init: RequestInit & { idempotencyKey?: string } = {}): Promise<T> {
80	  const token = await getAccessToken();
81	  const headers: Record<string, string> = {
82	    Authorization: `Bearer ${token}`,
83	    "Content-Type": "application/json",
84	    ...(init.headers as Record<string, string> | undefined),
85	  };
86	  if (init.idempotencyKey) headers["PayPal-Request-Id"] = init.idempotencyKey;
87	  const res = await fetch(`${apiBase()}${path}`, { ...init, headers });
88	  const text = await res.text();
89	  let json: unknown = null;
90	  try {
91	    json = text ? JSON.parse(text) : null;
92	  } catch {
93	    /* non-JSON error body — fall through with json === null */
94	  }
95	  if (!res.ok) {
96	    const detail = json && typeof json === "object" ? JSON.stringify(json) : text;
97	    throw new Error(`PayPal API ${path} failed: ${res.status} ${detail}`.slice(0, 1000));
98	  }
99	  return json as T;
100	}
