102	export type PayPalOrder = {
103	  id: string;
104	  status: string;
105	  purchase_units?: Array<{ custom_id?: string; amount?: { currency_code: string; value: string } }>;
106	};
107	
108	/**
109	 * The vault block PayPal echoes back on a captured order's
110	 * `payment_source.paypal.attributes.vault` when vaulting was requested and
111	 * succeeded, plus the payer's PayPal email from `payment_source.paypal`
112	 * itself. Both are OPTIONAL in every response type below — vaulting is a
113	 * best-effort request, never assumed to have succeeded until this is present.
114	 */
115	export type PayPalVaultedOrder = PayPalOrder & {
116	  purchase_units?: Array<{
117	    custom_id?: string;
118	    amount?: { currency_code: string; value: string };
119	    payments?: { captures?: Array<{ id: string; status: string; amount?: { currency_code: string; value: string } }> };
120	  }>;
121	  payment_source?: {
122	    paypal?: {
123	      email_address?: string;
124	      attributes?: { vault?: { id?: string; status?: string } };
125	    };
126	  };
127	};
128	
129	/**
130	 * Create a PayPal order for `amountCents` (a REAL server-computed price, never a
131	 * client-supplied number). `pendingId` is the id of the `PendingExternalPayment`
132	 * row this order is for — it rides as `custom_id`, PayPal's one small
133	 * (127-char) free-form field, so the full order metadata never needs to reach
134	 * PayPal at all; PayPal is only ever asked to move money and echo the id back.
135	 *
136	 * `vault: true` additionally asks PayPal to store this buyer's PayPal payment
137	 * method for future MERCHANT-initiated charges (renewals) — see
138	 * `payment_source.paypal.attributes.vault` in PayPal's Orders v2 docs.
139	 * `store_in_vault: "ON_SUCCESS"` only stores it once the payment actually
140	 * completes, so a failed/abandoned checkout never leaves a half-saved method
141	 * behind. This is a best-effort REQUEST: PayPal may decline to vault (account
142	 * not eligible, buyer declines) without failing the underlying payment, so the
143	 * caller must always check the capture response's `attributes.vault.id`
144	 * before assuming anything was saved (see `savePayPalVaultFromCapture`).
145	 */
146	export async function createPayPalOrder(opts: {
147	  amountCents: number;
148	  currency?: string;
149	  pendingId: string;
150	  description: string;
151	  vault?: boolean;
152	}): Promise<PayPalOrder> {
153	  if (!(opts.amountCents > 0)) throw new Error("PayPal order amount must be positive");
154	  const value = (opts.amountCents / 100).toFixed(2);
155	  return paypalFetch<PayPalOrder>("/v2/checkout/orders", {
156	    method: "POST",
157	    idempotencyKey: `nxeon_pp_create_${opts.pendingId}`,
158	    body: JSON.stringify({
159	      intent: "CAPTURE",
160	      ...(opts.vault
161	        ? {
162	            payment_source: {
163	              paypal: {
164	                attributes: {
165	                  vault: { store_in_vault: "ON_SUCCESS", usage_type: "MERCHANT", customer_type: "CONSUMER" },
166	                },
167	              },
168	            },
169	          }
170	        : {}),
171	      purchase_units: [
172	        {
173	          custom_id: opts.pendingId,
174	          description: opts.description.slice(0, 127),
175	          amount: { currency_code: (opts.currency ?? "USD").toUpperCase(), value },
176	        },
177	      ],
178	    }),
179	  });
180	}
181	
182	/**
183	 * Capture a PayPal order server-to-server. This — not anything the browser's
184	 * `onApprove` callback reports — is the authoritative "did the money move"
185	 * answer. Idempotent: PayPal returns the existing capture on a repeated call for
186	 * an order already captured (COMPLETED), so the client-driven capture and the
187	 * webhook backstop can race safely, exactly like the Stripe confirm/webhook race.
188	 */
189	export async function capturePayPalOrder(orderId: string): Promise<PayPalVaultedOrder> {
190	  return paypalFetch(`/v2/checkout/orders/${encodeURIComponent(orderId)}/capture`, {
191	    method: "POST",
192	    idempotencyKey: `nxeon_pp_capture_${orderId}`,
193	  });
194	}
195	
196	/**
197	 * Read back an order (used by the webhook, which only gets an id in the
198	 * event). A GET on an already-captured order echoes the same
199	 * `payment_source.paypal` block the capture response does, so the webhook
200	 * backstop can recover vault info the same way the client-driven capture
201	 * does — see `vaultInfoFromCapture`.
202	 */
203	export async function getPayPalOrder(orderId: string): Promise<PayPalVaultedOrder> {
204	  return paypalFetch(`/v2/checkout/orders/${encodeURIComponent(orderId)}`, { method: "GET" });
205	}
206	
207	/**
208	 * Pull the vault id + payer email off a captured order's response, if PayPal
209	 * actually vaulted it. Pure — no DB access, kept out of this file on purpose
210	 * (see the file header: this module is a plain API client; persistence lives
211	 * in lib/actions-payment-providers.ts, mirroring lib/stripe.ts vs
212	 * lib/stripe-cards.ts). Returns null when vaulting wasn't requested or PayPal
213	 * declined to vault it — a silent, non-fatal case, exactly like
214	 * `createPayPalOrder`'s vault request being best-effort.
215	 */
216	export function vaultInfoFromCapture(captured: PayPalVaultedOrder): { vaultId: string; payerEmail: string | null } | null {
217	  const vaultId = captured.payment_source?.paypal?.attributes?.vault?.id;
218	  if (!vaultId) return null;
219	  return { vaultId, payerEmail: captured.payment_source?.paypal?.email_address ?? null };
220	}
221	
222	/** True when this account can actually be charged via a saved PayPal method right now. */
223	export function hasChargeablePayPal(user: { paypalVaultId: string | null }): boolean {
224	  return paypalConfigured() && !!user.paypalVaultId;
225	}
226	
227	export type PayPalOffSessionResult =
228	  /** Money captured. `amountCents` is what PayPal actually took. */
229	  | { ok: true; captureId: string; amountCents: number }
230	  /** PayPal declined the charge outright — a real dunning event. */
231	  | { ok: false; kind: "declined"; message: string }
232	  /** Our side or PayPal's side wobbled. Not the customer's fault — never dun for it. */
233	  | { ok: false; kind: "transient"; message: string }
234	  /** Nothing to charge with (no vault, PayPal off, bad amount). */
235	  | { ok: false; kind: "unavailable"; message: string };
236	
237	/**
238	 * Charge a previously-vaulted PayPal payment method off-session (no buyer
239	 * present) — the PayPal analogue of `chargeSavedCardOffSession`
240	 * (lib/stripe-cards.ts), for a renewal whose customer has a saved PayPal
241	 * method but no saved card.
242	 *
243	 * `stored_credential` with `payment_initiator: "MERCHANT"` is what tells
244	 * PayPal this is a merchant-initiated charge against a consent already given
245	 * when the vault was created (store_in_vault above) — PayPal's documented
246	 * shape for using a payment method token to "create merchant-initiated
247	 * purchases and capture recurring payments" (Orders v2 create-order).
248	 *
249	 * VERIFY BEFORE ENABLING LIVE: this request shape is built from PayPal's
250	 * published documentation but has not yet been exercised against a real
251	 * PayPal sandbox or production charge from this codebase. The caller
252	 * (worker/billing.ts) gates this entirely behind the
253	 * `renewals_paypal_fallback_enabled` admin setting, defaulted OFF — flip it
254	 * on only after confirming one real charge succeeds end-to-end.
255	 *
256	 * Idempotency: unlike Stripe's `findChargeByMarker` (a live PaymentIntent
257	 * lookup by metadata), PayPal's Orders API has no equivalent server-side
258	 * search by custom metadata — so the durable "have we already charged this
259	 * period" guard lives in OUR OWN database instead (the caller checks for an
260	 * existing WalletTransaction whose description embeds `idempotencyKey`
261	 * before ever calling this function). `idempotencyKey` here only drives
262	 * PayPal's own short-lived `PayPal-Request-Id` replay protection, the same
263	 * role Stripe's `idempotencyKey` param plays for `chargeSavedCardOffSession`.
264	 */
265	export async function chargeVaultedPayPalOffSession(opts: {
266	  vaultId: string;
267	  amountCents: number;
268	  currency?: string;
269	  description: string;
270	  idempotencyKey: string;
271	}): Promise<PayPalOffSessionResult> {
272	  if (!paypalConfigured()) return { ok: false, kind: "unavailable", message: "PayPal is not configured" };
273	  if (!opts.vaultId) return { ok: false, kind: "unavailable", message: "No saved PayPal method" };
274	  if (!(opts.amountCents > 0)) return { ok: false, kind: "unavailable", message: "Invalid amount" };
275	
276	  const value = (opts.amountCents / 100).toFixed(2);
277	  let order: PayPalVaultedOrder;
278	  try {
279	    order = await paypalFetch<PayPalVaultedOrder>("/v2/checkout/orders", {
280	      method: "POST",
281	      idempotencyKey: `${opts.idempotencyKey}_create`,
282	      body: JSON.stringify({
283	        intent: "CAPTURE",
284	        payment_source: {
285	          paypal: {
286	            vault_id: opts.vaultId,
287	            stored_credential: {
288	              payment_initiator: "MERCHANT",
289	              usage: "SUBSEQUENT",
290	              usage_pattern: "RECURRING_POSTPAID",
291	            },
292	          },
293	        },
294	        purchase_units: [{ description: opts.description.slice(0, 127), amount: { currency_code: (opts.currency ?? "USD").toUpperCase(), value } }],
295	      }),
296	    });
297	  } catch (e) {
298	    console.error("[paypal] off-session order create failed", e);
299	    return { ok: false, kind: "transient", message: String((e as Error)?.message ?? e).slice(0, 300) };
300	  }
301	
302	  // A merchant-initiated order against a vaulted method may already read
303	  // COMPLETED on creation, or may still need the explicit capture step —
304	  // PayPal's docs don't pin this down for every account/processor path, so
305	  // both are handled rather than assumed.
306	  let captured = order;
307	  if (order.status !== "COMPLETED") {
308	    try {
309	      captured = await capturePayPalOrder(order.id);
310	    } catch (e) {
311	      console.error("[paypal] off-session capture failed", order.id, e);
312	      return { ok: false, kind: "transient", message: String((e as Error)?.message ?? e).slice(0, 300) };
313	    }
314	  }
315	
316	  const capture = captured.purchase_units?.[0]?.payments?.captures?.[0];
317	  if (captured.status !== "COMPLETED" || !capture) {
318	    return { ok: false, kind: "declined", message: `PayPal reported this payment as "${captured.status}"` };
319	  }
320	  const capturedCents = Math.round(Number(capture.amount?.value ?? "0") * 100);
321	  return { ok: true, captureId: capture.id, amountCents: capturedCents || opts.amountCents };
322	}
323	
324	/**
325	 * Verify a webhook really came from PayPal using PayPal's own server-to-server
326	 * verification endpoint (the documented method — no local certificate-chain
327	 * validation to get subtly wrong). Requires `PAYPAL_WEBHOOK_ID` (the id of the
328	 * webhook configured in the PayPal dashboard for this app). Returns false (never
329	 * throws) on any failure to verify or on missing configuration — a webhook that
330	 * cannot be PROVEN authentic must be rejected, not treated as authentic-by-default.
331	 */
332	export async function verifyPayPalWebhookSignature(
333	  headers: Headers,
334	  rawBody: string,
335	): Promise<boolean> {
336	  const webhookId = (process.env.PAYPAL_WEBHOOK_ID ?? "").trim();
337	  if (!paypalConfigured() || !webhookId) return false;
338	  let event: unknown;
339	  try {
340	    event = JSON.parse(rawBody);
341	  } catch {
342	    return false;
343	  }
344	  try {
345	    const result = await paypalFetch<{ verification_status: string }>("/v1/notifications/verify-webhook-signature", {
346	      method: "POST",
347	      body: JSON.stringify({
348	        auth_algo: headers.get("paypal-auth-algo"),
349	        cert_url: headers.get("paypal-cert-url"),
350	        transmission_id: headers.get("paypal-transmission-id"),
351	        transmission_sig: headers.get("paypal-transmission-sig"),
352	        transmission_time: headers.get("paypal-transmission-time"),
353	        webhook_id: webhookId,
354	        webhook_event: event,
355	      }),
356	    });
357	    return result.verification_status === "SUCCESS";
358	  } catch {
359	    return false;
360	  }
361	}
