188	/**
189	 * Capture a PayPal order server-to-server and fulfil it — the PayPal analogue of
190	 * the Stripe confirm route (app/api/stripe/confirm/route.ts). Called from the
191	 * wizard's `onApprove` callback; the PayPal webhook is the reliable backstop for
192	 * the same reason the Stripe webhook is (a closed tab must not be the only thing
193	 * that could have fulfilled a paid order). Idempotent via `fulfilExternalPayment`'s
194	 * FulfilledSession claim, so this racing the webhook is safe.
195	 */
196	export async function captureExternalPayPalOrder(
197	  paypalOrderId: string,
198	  pendingId: string,
199	): Promise<{ redirect?: string; error?: string }> {
200	  const user = await requireUser();
201	  const row = await db.pendingExternalPayment.findUnique({ where: { id: pendingId } });
202	  if (!row || row.userId !== user.id || row.provider !== "paypal") {
203	    return { error: "We couldn't find that payment." };
204	  }
205	
206	  let captured;
207	  try {
208	    captured = await capturePayPalOrder(paypalOrderId);
209	  } catch (e) {
210	    console.error("[payments] PayPal capture failed", paypalOrderId, e);
211	    return { error: "We couldn't confirm that PayPal payment. If you were charged, contact support — your money is safe." };
212	  }
213	  if (captured.status !== "COMPLETED") {
214	    return { error: `PayPal reported this payment as "${captured.status}" — please try again or use another method.` };
215	  }
216	  // Defence in depth: the captured amount must match what we asked PayPal to
217	  // charge. It always will (we set it), but a mismatch here means something is
218	  // wrong enough that fulfilling on trust would be the bug, not the fix.
219	  const capturedCents = Math.round(
220	    Number(captured.purchase_units?.[0]?.payments?.captures?.[0]?.amount?.value ?? "0") * 100,
221	  );
222	  if (capturedCents !== row.amountCents) {
223	    console.error("[payments] PayPal captured amount mismatch", { paypalOrderId, capturedCents, expected: row.amountCents });
224	    return { error: "That payment didn't match the expected amount. Contact support — nothing has been provisioned." };
225	  }
226	
227	  // Best-effort, mirrors saveCardFromPaymentSession (lib/stripe-cards.ts): the
228	  // money has already been confirmed above, so a failure here must be inert
229	  // and never turn a successful payment into a reported error.
230	  const vault = vaultInfoFromCapture(captured);
231	  if (vault) {
232	    try {
233	      await db.user.update({
234	        where: { id: user.id },
235	        data: { paypalVaultId: vault.vaultId, paypalPayerEmail: vault.payerEmail },
236	      });
237	    } catch (e) {
238	      console.error("[payments] could not record vaulted PayPal method", e);
239	    }
240	  }
241	
242	  try {
243	    const result: FulfilResult = await fulfilExternalPayment({
244	      provider: "paypal",
245	      externalId: paypalOrderId,
246	      pendingId,
247	      base: appBase(),
248	    });
249	    return { redirect: result.redirect };
250	  } catch (e) {
251	    console.error("[payments] PayPal fulfilment failed", paypalOrderId, e);
252	    return { error: "Your PayPal payment went through but we couldn't finish setup. Contact support — your money is safe and we've been alerted." };
253	  }
254	}
