257	 * VPS order — mirrors payAndDeploy's quote/promo/coupon/tax path
258	 * (lib/actions.ts) up to the point of opening a payment session.
259	 * ------------------------------------------------------------------ */
260	
261	async function quoteVpsOrderForExternalPayment(formData: FormData): Promise<
262	  | { error: string }
263	  | {
264	      cardCents: number;
265	      metadata: Record<string, string>;
266	      release: () => Promise<void>;
267	    }
268	> {
269	  const user = await requireUser();
270	  await assertNotImpersonating();
271	  const unverified = await emailVerificationError(user);
272	  if (unverified) return { error: unverified };
273	  const limitErr = await serverLimitError(user.id);
274	  if (limitErr) return { error: limitErr };
275	
276	  const intent = intentFromFormData(formData);
277	  intent.partnerSource = partnerSourceFromCookie(await cookies());
278	
279	  let quote;
280	  try {
281	    quote = await orderQuote(intent);
282	  } catch (e) {
283	    if (e instanceof OrderError) return { error: e.message };
284	    throw e;
285	  }
286	
287	  const promoIpHash = hashIp(clientIp(await headers()), process.env.AUTH_SECRET ?? "nxeon") || null;
288	  if (quote.promoCreditCents > 0 && !(await firstMonthFreeEligible(user.id, promoIpHash))) {
289	    quote = await orderQuote(intent, { suppressPromo: true });
290	  }
291	  const promoCampaign = promoCampaignFromCookie(await cookies());
292	
293	  const useWallet = formData.get("useWallet") !== "0";
294	  const taxCtx = await taxContextForUser(user);
295	  const taxOn = (netCents: number) => Math.round((netCents * taxCtx.ratePercent) / 100);
296	  const dueWithTax = (netCents: number) => netCents + taxOn(netCents);
297	  let { cardCents } = walletSplit({ dueCents: dueWithTax(quote.chargeCents), balanceCents: user.balanceCents, useWallet });
298	
299	  if (cardCents <= 0) {
300	    return { error: "Your wallet balance already covers this order — deploy it from the Review step without a card." };
301	  }
302	
303	  let promoReservationToken: string | null = null;
304	  let couponReservationToken: string | null = null;
305	  let checkoutIntent = intent;
306	
307	  if (quote.promoCreditCents > 0) {
308	    const reservedUntil = new Date(Date.now() + PAYPAL_HOLD_MS);
309	    const res = await reserveFirstMonthFree({
310	      userId: user.id,
311	      ipHash: promoIpHash,
312	      serviceType: "VPS",
313	      campaign: promoCampaign,
314	      chargedCents: quote.chargeCents,
315	      reservedUntil,
316	    });
317	    if (res.reserved) {
318	      promoReservationToken = res.token;
319	    } else {
320	      quote = await orderQuote(intent, { suppressPromo: true });
321	      ({ cardCents } = walletSplit({ dueCents: dueWithTax(quote.chargeCents), balanceCents: user.balanceCents, useWallet }));
322	      if (cardCents <= 0) {
323	        return { error: "Your wallet balance already covers this order at full price — deploy it from the Review step." };
324	      }
325	    }
326	  }
327	
328	  if (quote.couponId && quote.couponDiscountCents > 0) {
329	    const reservedUntil = new Date(Date.now() + PAYPAL_HOLD_MS);
330	    const res = await reserveOrderCoupon({
331	      couponId: quote.couponId,
332	      maxRedemptions: quote.couponMaxRedemptions,
333	      firstTimeOnly: quote.couponFirstTimeOnly,
334	      userId: user.id,
335	      ipHash: promoIpHash,
336	      amountCents: quote.couponDiscountCents,
337	      reservedUntil,
338	    });
339	    if (res.reserved) {
340	      couponReservationToken = res.token;
341	    } else {
342	      checkoutIntent = { ...intent, couponCode: undefined };
343	      quote = await orderQuote(checkoutIntent, { suppressPromo: !promoReservationToken });
344	      ({ cardCents } = walletSplit({ dueCents: dueWithTax(quote.chargeCents), balanceCents: user.balanceCents, useWallet }));
345	    }
346	  }
347	
348	  const release = async () => {
349	    if (promoReservationToken) await releaseReservation(promoReservationToken).catch(() => {});
350	    if (couponReservationToken) await releaseOrderCouponReservation(couponReservationToken).catch(() => {});
351	  };
352	
353	  const slim: OrderIntent = { ...checkoutIntent, sshPublicKey: undefined, sshKeyName: undefined };
354	  const sold: OrderPrice = orderPriceOf(quote, { taxCents: taxOn(quote.chargeCents), ratePercent: taxCtx.ratePercent, country: taxCtx.country });
355	  const metadata: Record<string, string> = {
356	    nxeonUserId: user.id,
357	    nxeonOrder: packExternalPaymentMetadata("Order intent", slim),
358	    nxeonOrderPrice: packExternalPaymentMetadata("Order price", sold),
359	    nxeonPromoCampaign: promoCampaign ?? "",
360	    ...(promoReservationToken ? { nxeonPromoReservation: promoReservationToken } : {}),
361	    ...(couponReservationToken ? { nxeonCouponReservation: couponReservationToken } : {}),
362	  };
363	
364	  return { cardCents, metadata, release };
365	}
