1	import { NextRequest, NextResponse } from "next/server";
2	import { paypalConfigured, verifyPayPalWebhookSignature, getPayPalOrder, vaultInfoFromCapture } from "@/lib/paypal";
3	import { fulfilExternalPayment } from "@/lib/fulfil-checkout";
4	import { db } from "@/lib/db";
