1	// Single fulfilment path for a paid Stripe Checkout session, shared by BOTH the
2	// success-redirect route and the webhook. Plain server module (not "use server").
3	//
4	// WHY THIS EXISTS (2026-07-25)
5	// Fulfilment used to live in `app/api/stripe/confirm/route.ts` and was gated on
6	// whether `creditCheckoutSession()` returned true. That boolean is true only for
7	// the caller that won the race to insert the wallet credit — and the webhook
8	// calls the same function and discards the result. So:
9	//
10	//   * Race: the webhook's insert lands first, the confirm request gets P2002,
11	//     `credited === false`, and the redirect quietly lands on an empty page.
12	//     $249 charged, $249 credited, no server, no error, no notification.
13	//   * Deterministic: the customer closes the tab before `success_url` resolves,
14	//     so the confirm route never runs at all. Same outcome, 100% reproducible.
15	//
16	// Stripe's own guidance is explicit that a browser redirect must not be the
17	// fulfilment trigger. Now BOTH callers run this, and a `FulfilledSession` row —
18	// its own marker, not a side effect of crediting — decides the single winner.
19	
20	import type Stripe from "stripe";
21	import { db } from "./db";
22	import {
23	  classifyCheckoutSession,
24	  creditCheckoutSession,
25	  retrieveCheckoutSession,
26	  isPurchaseLegSession,
27	  packMetadata,
28	  STRIPE_METADATA_VALUE_MAX,
29	  type CheckoutPurpose,
30	} from "./stripe";
31	import { saveCardFromPaymentSession } from "./stripe-cards";
32	import { placeOrder } from "./order";
33	import { placeGameOrder } from "./game-order";
34	import { placeHostingCardOrder } from "./actions-hosting";
35	import { placeEmailCardOrder } from "./actions-email-hosting";
36	import { placeDomainCardOrder } from "./actions-domains";
37	import { applyResize } from "./resize";
38	import { applyDiskExpand } from "./disk-expand";
39	import { recordDeployFunnelError } from "./deploy-funnel";
40	import { sendMetaConversion } from "./tracking";
41	import { cookies, headers } from "next/headers";
42	
43	/**
44	 * Which rail actually moved the money. Stripe is the only one with a real
45	 * Checkout Session (so `saveCardFromPaymentSession` and the Stripe-specific
46	 * ledger label only ever run for it); PayPal and Coinbase Commerce reach this
47	 * same dispatch through `fulfilExternalPayment` below with a SYNTHETIC
48	 * session-shaped object carrying the identical nxeon* metadata keys.
49	 */
50	export type PaymentProvider = "stripe" | "paypal" | "coinbase";
51	
52	export type FulfilResult = {
53	  /** Where the browser should end up. The webhook ignores this. */
54	  redirect: string;
55	  /** True when THIS call performed the fulfilment work. */
56	  fulfilled: boolean;
57	  kind: "order" | "gameOrder" | "hostOrder" | "emailOrder" | "domainOrder" | "resize" | "diskExpand" | "topup" | "none";
58	  error?: string;
59	};
60	
61	/**
62	 * Claim exclusive responsibility for fulfilling `sessionId`.
63	 * Returns false when another caller already holds the claim — the UNIQUE index,
64	 * not a read-then-write check, is what makes this safe under concurrency.
65	 */
66	async function claim(sessionId: string, kind: string): Promise<boolean> {
67	  try {
68	    await db.fulfilledSession.create({ data: { stripeSessionId: sessionId, kind } });
69	    return true;
70	  } catch (e) {
71	    if ((e as { code?: string })?.code === "P2002") return false; // someone else has it
72	    throw e;
73	  }
74	}
75	
76	async function settle(sessionId: string, status: "DONE" | "FAILED", detail?: string) {
77	  await db.fulfilledSession
78	    .update({ where: { stripeSessionId: sessionId }, data: { status, detail: detail?.slice(0, 500) } })
79	    .catch(() => {});
80	}
81	
82	/**
83	 * Tell the customer their money is safe and someone knows. Called only on a path
84	 * where the card HAS cleared and fulfilment did not happen, so silence is the one
85	 * outcome that is never acceptable.
86	 */
87	async function notifyStalled(userId: string) {
88	  await db.notification
89	    .create({
90	      data: {
91	        userId,
92	        title: "Payment received — we couldn't finish setting up your server",
93	        body: "Your payment is safe and sitting in your wallet. Our team has been alerted; deploy again or contact support and we'll sort it out.",
94	        href: "/dashboard/billing",
95	      },
96	    })
97	    .catch(() => {});
98	}
99	
100	/**
101	 * Report a completed order as an ad-conversion, exactly once, on the WINNING fulfil
102	 * call (this only runs where `fulfilled === true`, so no double count under the
103	 * redirect/webhook race). Fires the server-side Meta Conversions API event — best
104	 * effort, inert unless the pixel id + CAPI token are set, and it never throws into
105	 * fulfilment — then returns the redirect tagged with the SAME event_id and the real
106	 * charged amount (`session.amount_total`, what Stripe actually took), so the browser
107	 * pixel (`PurchaseTracker`) can fire and Meta dedupes the pair into ONE conversion.
108	 * READ-ONLY on money: it reports the amount, it never changes a charge.
109	 */
110	async function reportPurchase(
111	  redirect: string,
112	  session: Awaited<ReturnType<typeof retrieveCheckoutSession>>,
113	  email?: string,
114	  userId?: string,
115	  /** Product kind for the per-funnel Google Ads conversion ("vps" | "game"). */
116	  prod?: string,
117	): Promise<string> {
118	  const value = typeof session.amount_total === "number" ? session.amount_total / 100 : 0;
119	  if (!(value > 0)) return redirect; // free / zero-charge order — nothing to report
120	  const currency = (session.currency ?? "usd").toUpperCase();
121	  // Best-effort match signals from the request: the Meta _fbc/_fbp cookies + UA/IP.
122	  // Wrapped so the webhook path (no browser request scope) simply sends without them.
123	  let fbc: string | undefined, fbp: string | undefined, userAgent: string | undefined, clientIp: string | undefined;
124	  try {
125	    const [ck, h] = await Promise.all([cookies(), headers()]);
126	    fbc = ck.get("_fbc")?.value || undefined;
127	    fbp = ck.get("_fbp")?.value || undefined;
128	    userAgent = h.get("user-agent") ?? undefined;
129	    clientIp = (h.get("x-forwarded-for")?.split(",")[0] ?? "").trim() || undefined;
130	  } catch {
131	    /* no request scope (webhook) — send without cookie/UA signals */
132	  }
133	  const { eventId } = await sendMetaConversion({
134	    eventName: "Purchase",
135	    email,
136	    value,
137	    currency,
138	    sourceUrl: redirect,
139	    fbc,
140	    fbp,
141	    userAgent,
142	    clientIp,
143	    externalId: userId,
144	  });
145	  // SERVER-SIDE Google Ads offline conversion for the paid order, using the captured
146	  // gclid — reliable where the browser gtag is not. Best-effort + idempotent (deduped
147	  // on the Stripe session id). Fires the product-specific action (vps/hosting/game/…)
148	  // AND a generic "purchase". Inert until the Ads API creds are configured.
149	  if (userId) {
150	    try {
151	      const { recordAdsConversion } = await import("./google-ads");
152	      const valueCents = Math.round(value * 100);
153	      if (prod) await recordAdsConversion({ kind: prod, userId, dedupeKey: `${prod}:${session.id}`, valueCents, currency });
154	      await recordAdsConversion({ kind: "purchase", userId, dedupeKey: `purchase:${session.id}`, valueCents, currency });
155	    } catch {
156	      /* tracking is best-effort — the order is already fulfilled */
157	    }
158	  }
159	  const params = new URLSearchParams({ purchase: "1", pv: value.toFixed(2), pc: currency, pe: eventId, ...(prod ? { prod } : {}) });
160	  return `${redirect}${redirect.includes("?") ? "&" : "?"}${params.toString()}`;
161	}
162	
163	/**
164	 * Credit the wallet and fulfil whatever the session was for, exactly once.
165	 * Safe to call repeatedly and concurrently from the redirect and the webhook.
166	 *
167	 * THROWS when Stripe cannot be read. That is deliberate and it is the fix for the
168	 * defect found on 2026-07-27: this function used to ask three helpers for the
169	 * session, each of which swallowed every error into `null`, so a transient Stripe
170	 * failure was indistinguishable from "no purchase metadata" and fell through to
171	 * the top-up branch below reporting `fulfilled: true`. A real order then had its
172	 * card charged with no server, no FulfilledSession row and no notification — and
173	 * because the webhook returns 200 either way, Stripe never retried it. A throw
174	 * lands the browser on `?pending=1` (see app/api/stripe/confirm) and puts the
175	 * failure in the webhook's log, which is loud; declaring it a top-up was silent.
176	 */
177	export async function fulfilCheckoutSession(sessionId: string, base = ""): Promise<FulfilResult> {
178	  // ONE retrieve, one view of the session, shared by the credit and the routing.
179	  const session = await retrieveCheckoutSession(sessionId);
180	  const purpose = classifyCheckoutSession(session);
181	  return runFulfilment(session, purpose, base, "stripe");
182	}
183	
184	/**
185	 * The actual dispatch, factored out of `fulfilCheckoutSession` so
186	 * `fulfilExternalPayment` (PayPal / Coinbase Commerce, below) can drive the exact
187	 * same claim/credit/provision/settle/notify logic from a SYNTHETIC session-shaped
188	 * object instead of a real Stripe retrieve. Nothing in this function's body
189	 * changed from the original `fulfilCheckoutSession` other than: (a) `sessionId` is
190	 * now read off `session.id` instead of being a separate parameter, and (b) the two
191	 * spots that are genuinely Stripe-only — crediting the wallet, and recording the
192	 * card for renewals — are gated on `provider === "stripe"`. Every claim/settle/
193	 * notify/provisioning line is untouched.
194	 */
195	async function runFulfilment(
196	  session: Stripe.Checkout.Session,
197	  purpose: CheckoutPurpose,
198	  base: string,
199	  provider: PaymentProvider,
200	): Promise<FulfilResult> {
201	  const sessionId = session.id;
202	
203	  // Nothing was paid (an abandoned session id, or one replayed before capture).
204	  // Never claim fulfilment for money that has not arrived.
205	  if (purpose.kind === "unpaid") {
206	    return { redirect: `${base}/dashboard/billing`, fulfilled: false, kind: "none" };
207	  }
208	
209	  // Crediting is separately idempotent (UNIQUE stripeSessionId on the wallet
210	  // transaction). We deliberately IGNORE its return value now — it reports who
211	  // won the credit race, which is not the same question as "has this been
212	  // fulfilled", and conflating the two was the bug. A THROW, however, is not a
213	  // race: the money has not reached the wallet, so nothing below may spend it.
214	  //
215	  // `creditCheckoutSession` itself is Stripe-specific (it types its argument as a
216	  // real `Stripe.Checkout.Session`); PayPal/Coinbase route through
217	  // `creditExternalPayment` instead, which writes the identical
218	  // WalletTransaction/User.balanceCents/notification shape but with an honest
219	  // ledger label (never "Stripe payment" for money PayPal or Coinbase moved) and
220	  // no invoice branch, since every external-payment kind reaching this function is
221	  // a purchase leg, never a bare top-up — see that function's doc comment.
222	  if (provider === "stripe") {
223	    await creditCheckoutSession(session);
224	  } else {
225	    await creditExternalPayment(session, provider);
226	  }
227	
228	  // Purchase metadata is present but cannot be trusted. Retrying will never fix
229	  // it, so claim the session and record the failure exactly like a failed order:
230	  // reconcilable, and the customer is told. What it must NEVER become is a silent
231	  // wallet top-up, which is precisely what the old `null` fall-through produced.
232	  if (purpose.kind === "unreadable") {
233	    if (await claim(sessionId, "unreadable")) {
234	      await settle(sessionId, "FAILED", purpose.detail);
235	      if (purpose.userId) await notifyStalled(purpose.userId);
236	    }
237	    return {
238	      redirect: `${base}/dashboard/billing?paid=1`,
239	      fulfilled: false,
240	      kind: "none",
241	      error: purpose.detail,
242	    };
243	  }
244	
245	  const order = purpose.kind === "order" ? purpose : null;
246	  if (order) {
247	    if (!(await claim(sessionId, "order"))) {
248	      return { redirect: `${base}/dashboard/servers`, fulfilled: false, kind: "order" };
249	    }
250	    try {
251	      const user = await db.user.findUnique({ where: { id: order.userId } });
252	      if (!user) throw new Error("user not found for paid order");
253	      // Settle the price stamped on the session BEFORE the card was charged — never
254	      // a fresh quote taken now. The customer has already paid the card leg of that
255	      // exact total; re-pricing here and taking the difference out of the wallet is
256	      // the H2 incident (see OrderPrice in lib/order.ts). This is the same shape as
257	      // the resize and disk-expand branches below, which have always passed the
258	      // amount through metadata for this reason.
259	      // No request-scoped IP on the fulfil path (this can run in the webhook), so the
260	      // per-IP cap can't be enforced here — the per-account unique still holds, and
261	      // the first-month-free HOLD was already reserved (per-account AND per-IP) before
262	      // the card was charged, so the double-claim race is closed regardless. Fulfilment
263	      // CONFIRMS that hold via `promoReservationToken` rather than contending for a
264	      // fresh claim. `campaign` rides in via metadata so attribution survives the card
265	      // round-trip even in the webhook (no cookies).
266	      const serverId = await placeOrder(user, order.intent, order.sold, {
267	        ipHash: null,
268	        campaign: order.campaign,
269	        promoReservationToken: order.promoReservationToken,
270	        // Same discipline as the promo hold: the coupon was RESERVED (per-person + global
271	        // cap) before the card was charged, and placeOrder CONFIRMS that hold via this
272	        // token rather than contending for a fresh claim — no double-claim, no over-charge.
273	        couponReservationToken: order.couponReservationToken,
274	      });
275	      await settle(sessionId, "DONE", serverId);
276	      // Record the card this order was paid with (the session set
277	      // setup_future_usage) so the renewal sweep can auto-charge it next cycle.
278	      // Guarded: the money moved and the server exists — card recording must never
279	      // turn a completed fulfilment into a failure.
280	      if (provider === "stripe") {
281	        try {
282	          await saveCardFromPaymentSession(session, order.userId);
283	        } catch {
284	          /* best-effort: fulfilment already succeeded */
285	        }
286	      }
287	      const redirect = await reportPurchase(`${base}/dashboard/servers/${serverId}`, session, user.email, user.id, "vps");
288	      return { redirect, fulfilled: true, kind: "order" };
289	    } catch (e) {
290	      // Payment is captured and the funds are in the wallet — record the failure
291	      // so it is reconcilable rather than invisible, and tell the customer.
292	      const msg = String((e as Error)?.message ?? e);
293	      await settle(sessionId, "FAILED", msg);
294	      await notifyStalled(order.userId);
295	      // Deploy-funnel: the card CLEARED but the order couldn't be placed — the one
296	      // payment-tail failure only visible server-side (the browser has left the
297	      // wizard, or this is the webhook). Recording it on the Payment step lets the
298	      // admin funnel tell "paid, then failed" from a plain abandon. Best-effort +
299	      // guarded so it never re-enters the money path we're unwinding.
300	      try {
301	        await recordDeployFunnelError({ product: "vps", step: "Payment", stepIndex: 7, errorCode: "PAID_ORDER_FAILED", errorMessage: msg, userId: order.userId });
302	      } catch {
303	        /* analytics must never disturb fulfilment */
304	      }
305	      return { redirect: `${base}/dashboard/deploy?paid=1`, fulfilled: false, kind: "order", error: msg };
306	    }
307	  }
308	
309	  // Game-server order — the game analogue of the `order` branch above. Same claim /
310	  // settle / notify discipline; the card leg was credited to the wallet by
311	  // `creditCheckoutSession` above, then `placeGameOrder` debits the SOLD total back
312	  // out — never a fresh quote taken now (the H2 re-pricing incident). Game carries
313	  // no promo/coupon hold, so there is nothing to confirm and no per-IP concern here.
314	  const gameOrder = purpose.kind === "gameOrder" ? purpose : null;
315	  if (gameOrder) {
316	    if (!(await claim(sessionId, "gameOrder"))) {
317	      return { redirect: `${base}/dashboard/servers`, fulfilled: false, kind: "gameOrder" };
318	    }
319	    try {
320	      const user = await db.user.findUnique({ where: { id: gameOrder.userId } });
321	      if (!user) throw new Error("user not found for paid game order");
322	      const serverId = await placeGameOrder(user, gameOrder.intent, gameOrder.sold);
323	      await settle(sessionId, "DONE", serverId);
324	      // Save the card for off-session renewals (same guard as the order branch).
325	      if (provider === "stripe") {
326	        try {
327	          await saveCardFromPaymentSession(session, gameOrder.userId);
328	        } catch {
329	          /* best-effort: fulfilment already succeeded */
330	        }
331	      }
332	      const redirect = await reportPurchase(`${base}/dashboard/servers/${serverId}`, session, user.email, user.id, "game");
333	      return { redirect, fulfilled: true, kind: "gameOrder" };
334	    } catch (e) {
335	      // Payment is captured and the funds are in the wallet — record the failure so
336	      // it is reconcilable rather than invisible, and tell the customer.
337	      const msg = String((e as Error)?.message ?? e);
338	      await settle(sessionId, "FAILED", msg);
339	      await notifyStalled(gameOrder.userId);
340	      // Deploy-funnel: card cleared but the game order couldn't be placed — the same
