574	/* ------------------------------------------------------------------ *
575	 * PayPal / Coinbase Commerce — the SAME dispatch, a synthetic session
576	 * ------------------------------------------------------------------ */
577	
578	/**
579	 * Credit the wallet for a paid PayPal/Coinbase Commerce session — the non-Stripe
580	 * analogue of `creditCheckoutSession` (lib/stripe.ts). Deliberately a SEPARATE,
581	 * smaller function rather than a call into that one, for two reasons:
582	 *
583	 *  1. Honesty of the ledger. `creditCheckoutSession` hard-codes the wallet-
584	 *     transaction description as `Stripe payment (${session.id})`. Reusing it for
585	 *     PayPal/Coinbase would label a customer's PayPal or crypto payment as a
586	 *     "Stripe payment" in their own billing history AND in the admin refund
587	 *     tool's ledger search (`lib/actions-admin-billing.ts`'s `description:
588	 *     {contains: "Stripe payment (cs_"}` — that regex's `cs_` prefix requirement
589	 *     means a synthetic `paypal:`/`coinbase:` id would never match it anyway, so
590	 *     nothing is UNSAFE, but the label would still be a plain false statement.
591	 *  2. Every external-payment session reaching this function was created by our
592	 *     own `lib/actions-payment-providers.ts` order/charge-creation actions, which
593	 *     never create one without purchase metadata (order/gameOrder/hostOrder/
594	 *     emailOrder) — there is no "top up your wallet with PayPal/crypto" product.
595	 *     So unlike `creditCheckoutSession`, there is no top-up invoice branch here;
596	 *     `isPurchaseLegSession` is asserted rather than branched on, and a session
597	 *     that somehow fails it is refused loudly rather than silently treated as a
598	 *     top-up (exactly the "unrecognised metadata → top-up" bug `packMetadata`'s
599	 *     doc comment and the `unreadable` classification exist to end — the failure
600	 *     mode this function must never reintroduce from a different code path).
601	 *
602	 * Idempotent the same way: UNIQUE(stripeSessionId) on `WalletTransaction`, so a
603	 * client-driven capture racing the provider's webhook is safe — P2002 means
604	 * someone else already credited this exact session id.
605	 */
606	async function creditExternalPayment(
607	  session: Stripe.Checkout.Session,
608	  provider: Exclude<PaymentProvider, "stripe">,
609	): Promise<boolean> {
610	  const userId = session.metadata?.nxeonUserId;
611	  const cents = session.amount_total ?? 0;
612	  if (!userId || cents <= 0 || session.payment_status !== "paid") return false;
613	
614	  if (!isPurchaseLegSession(session.metadata)) {
615	    throw new Error(
616	      `${provider} payment ${session.id} carries no recognised purchase metadata — refusing to treat unrecognised money as a top-up`,
617	    );
618	  }
619	
620	  const label = provider === "paypal" ? "PayPal" : "Coinbase Commerce";
621	  try {
622	    await db.$transaction([
623	      db.walletTransaction.create({
624	        data: {
625	          userId,
626	          amountCents: cents,
627	          description: `${label} payment (${session.id})`,
628	          stripeSessionId: session.id,
629	        },
630	      }),
631	      db.user.update({ where: { id: userId }, data: { balanceCents: { increment: cents } } }),
632	      db.notification.create({
633	        data: {
634	          userId,
635	          title: `Payment of $${(cents / 100).toFixed(2)} received`,
636	          href: "/dashboard/billing",
637	        },
638	      }),
639	    ]);
640	  } catch (e) {
641	    if ((e as { code?: string })?.code === "P2002") return false; // raced — already credited
642	    throw e;
643	  }
644	  // Best-effort side effects, same as creditCheckoutSession — never allowed to
645	  // turn a completed credit into a reported failure.
646	  try {
647	    const { maybeRewardReferral } = await import("./actions-growth");
648	    await maybeRewardReferral(userId);
649	  } catch {
650	    /* best-effort */
651	  }
652	  // No generic "Payment received" receipt here: every session this function
653	  // credits is a purchase leg (see this function's doc comment — there is no
654	  // "top up with PayPal/crypto" product), so the order this money is funding
655	  // sends its own specific, itemised invoice_new email moments later. Sending
656	  // both meant a generic, invoice-less "your Nxeon order" receipt landed right
657	  // before the real invoice on every PayPal/Coinbase purchase — the exact
658	  // "this email is weak" duplication already removed from the Stripe path in
659	  // creditCheckoutSession.
660	  return true;
661	}
