663	export type ExternalPaymentInput = {
664	  provider: Exclude<PaymentProvider, "stripe">;
665	  /** PayPal's order id, or Coinbase Commerce's charge code — the provider's own reference. */
666	  externalId: string;
667	  /** The `PendingExternalPayment` row id created when the order/charge was opened
668	   *  (lib/actions-payment-providers.ts) — the ONE place the full order metadata lives. */
669	  pendingId: string;
670	  base?: string;
671	};
672	
673	/**
674	 * Fulfil a PAID PayPal order or Coinbase Commerce charge through the EXACT SAME
675	 * `runFulfilment` dispatch Stripe's `fulfilCheckoutSession` uses — the seam this
676	 * whole module exists to provide. Builds a SYNTHETIC `Stripe.Checkout.Session`-
677	 * shaped object from the `PendingExternalPayment` row (same nxeon* metadata keys,
678	 * `payment_status: "paid"`, the row's own server-computed `amountCents`) and hands
679	 * it to `runFulfilment` with `provider` set so the two Stripe-only steps above are
680	 * skipped. There is exactly ONE dispatch function in this codebase; this is how a
681	 * second payment rail reaches it without a second copy of the claim/settle/
682	 * provision/notify logic.
683	 *
684	 * Callers: the PayPal capture server action (client-driven, like Stripe's confirm
685	 * redirect) AND the PayPal webhook (the reliable backstop) — the SAME
686	 * confirm/webhook race Stripe already runs safely, because the claim below is the
687	 * same `FulfilledSession` UNIQUE(stripeSessionId) index, just keyed
688	 * `"paypal:<orderId>"` instead of a Stripe session id. Coinbase Commerce has no
689	 * client-driven capture step (crypto confirmation only ever arrives by webhook),
690	 * so its webhook is the only caller — still idempotent on its own if Coinbase ever
691	 * redelivers the event.
692	 *
693	 * THROWS if the `PendingExternalPayment` row cannot be found or its stored
694	 * metadata is not valid JSON — the same "throw rather than silently misclassify"
695	 * discipline `retrieveCheckoutSession` and `fulfilCheckoutSession` already apply
696	 * to a Stripe read failure. A row that cannot be trusted must never fall through
697	 * to the top-up branch.
698	 */
699	export async function fulfilExternalPayment(input: ExternalPaymentInput): Promise<FulfilResult> {
700	  const row = await db.pendingExternalPayment.findUnique({ where: { id: input.pendingId } });
701	  if (!row) {
702	    throw new Error(`No PendingExternalPayment row for id ${input.pendingId} (${input.provider} ${input.externalId})`);
703	  }
704	  if (row.provider !== input.provider) {
705	    throw new Error(
706	      `PendingExternalPayment ${input.pendingId} provider mismatch: expected ${input.provider}, stored ${row.provider}`,
707	    );
708	  }
709	
710	  let metadata: Record<string, string>;
711	  try {
712	    const parsed = JSON.parse(row.metadata);
713	    if (!parsed || typeof parsed !== "object") throw new Error("not an object");
714	    metadata = parsed as Record<string, string>;
715	  } catch {
716	    throw new Error(`PendingExternalPayment ${input.pendingId} metadata is not readable JSON`);
717	  }
718	
719	  // The provider-qualified id IS the FulfilledSession/WalletTransaction claim key —
720	  // "paypal:5O190127TN364715T" can never collide with a real Stripe `cs_...` id or
721	  // with the other provider's charge codes.
722	  const sessionId = `${input.provider}:${input.externalId}`;
723	  const synthetic = {
724	    id: sessionId,
725	    metadata,
726	    payment_status: "paid",
727	    amount_total: row.amountCents,
728	    currency: row.currency,
729	    customer: null,
730	    payment_intent: null,
731	  } as unknown as Stripe.Checkout.Session;
732	
733	  const purpose = classifyCheckoutSession(synthetic);
734	
735	  try {
736	    const result = await runFulfilment(synthetic, purpose, input.base ?? "", input.provider);
737	    await db.pendingExternalPayment
738	      .update({ where: { id: row.id }, data: { status: "PAID", providerRef: input.externalId } })
739	      .catch(() => {});
740	    return result;
741	  } catch (e) {
742	    await db.pendingExternalPayment.update({ where: { id: row.id }, data: { status: "FAILED" } }).catch(() => {});
743	    throw e;
744	  }
745	}
746	
747	// Re-exported so callers building a PendingExternalPayment row's `metadata`
748	// column can reuse the SAME 500-char-per-value refuse-don't-truncate guard
749	// Stripe metadata uses, instead of a second copy of that safety property.
750	export { packMetadata as packExternalPaymentMetadata, STRIPE_METADATA_VALUE_MAX };
