261	function stripeFunctionBody(src: string, name: string): string {
262	  const start = src.indexOf(`function ${name}(`);
263	  assert.ok(start >= 0, `could not find function ${name} in lib/stripe.ts`);
264	  const parenStart = src.indexOf("(", start);
265	  let pdepth = 0;
266	  let parenEnd = -1;
267	  for (let i = parenStart; i < src.length; i++) {
268	    if (src[i] === "(") pdepth++;
269	    else if (src[i] === ")") {
270	      pdepth--;
271	      if (pdepth === 0) {
272	        parenEnd = i;
273	        break;
274	      }
275	    }
276	  }
277	  assert.ok(parenEnd >= 0, `unbalanced parens reading ${name}'s parameter list`);
278	  const openBrace = src.indexOf("{", parenEnd);
279	  let depth = 0;
280	  for (let i = openBrace; i < src.length; i++) {
281	    if (src[i] === "{") depth++;
282	    else if (src[i] === "}") {
283	      depth--;
284	      if (depth === 0) return src.slice(start, i + 1);
285	    }
286	  }
287	  throw new Error(`unbalanced braces reading ${name}`);
288	}
