export async function capturePayPalOrder(orderId: string): Promise<PayPalVaultedOrder> {
  return paypalFetch(`/v2/checkout/orders/${encodeURIComponent(orderId)}/capture`, {
    method: "POST",
    idempotencyKey: `nxeon_pp_capture_${orderId}`,
    // CRITICAL: PayPal's documented default for this endpoint is also
    // `Prefer: return=minimal` — a bare `{id, status, links}`, with NO
    // `purchase_units` and NO `payment_source` at all. Without this header every
    // caller here silently breaks: `captureExternalPayPalOrder`'s captured-amount
    // check reads `purchase_units[0].payments.captures[0].amount.value`, which
    // would be `undefined` -> computed as $0 -> ALWAYS mismatches the expected
    // amount -> every real PayPal payment gets rejected as "didn't match the
    // expected amount" even though PayPal genuinely captured the money.
    // `chargeVaultedPayPalOffSession`'s `!capture` check would likewise always be
    // true -> every renewal charge would be reported "declined" even when PayPal
    // actually took the customer's money, and `vaultInfoFromCapture` would never
    // see a vault id. This was caught during the pre-first-transaction audit by
    // reading PayPal's Orders v2 OpenAPI spec directly (both /v2/checkout/orders
    // and its /capture sub-resource default `Prefer` to `return=minimal`) — it had
    // never been exercised against a real capture, so nothing would have surfaced
    // this until the first live customer payment silently failed to fulfil.
    headers: { Prefer: "return=representation" },
  });
}

