import { test } from "node:test";
import assert from "node:assert/strict";

/**
 * Real behavioural tests for lib/paypal.ts's pure HTTP-client logic — the exact
 * request-shape-building code the 2026-08-29 pre-first-transaction audit was
 * asked to re-verify against PayPal's current Orders v2 API reference. Unlike
 * test/payment-providers.test.ts (which deliberately never imports a route
 * module that would pull in Prisma), lib/paypal.ts imports neither `./db` nor
 * any Next.js server-only API, so it is safe to import directly here and drive
 * with a mocked `fetch` — no database, no network.
 *
 * THE BUG THIS FILE PINS DOWN. PayPal's Orders v2 API defaults BOTH
 * `POST /v2/checkout/orders` and `POST /v2/checkout/orders/{id}/capture` to
 * `Prefer: return=minimal` — a bare `{id, status, links}` with NO
 * `purchase_units` and NO `payment_source` — unless the caller explicitly asks
 * for `return=representation` (confirmed against PayPal's own published
 * OpenAPI spec, github.com/paypal/paypal-rest-api-specifications). Before this
 * audit, nothing in this codebase ever sent that header, so:
 *   - `captureExternalPayPalOrder`'s captured-amount check would always read
 *     `undefined` -> compute $0 -> ALWAYS mismatch a real captured amount ->
 *     every genuine PayPal payment would have been rejected as "didn't match
 *     the expected amount", money taken with nothing provisioned.
 *   - `chargeVaultedPayPalOffSession`'s `!capture` check would always be true
 *     -> every renewal charge would report "declined" even when PayPal
 *     genuinely took the money.
 *   - `vaultInfoFromCapture` would never see a vault id to save.
 * This would have surfaced on literally the first real transaction. Fixed by
 * adding `Prefer: return=representation` to all three call sites; the tests
 * below fail again if that header is ever dropped.
 */

import {
  createPayPalOrder,
  capturePayPalOrder,
  chargeVaultedPayPalOffSession,
  vaultInfoFromCapture,
  hasChargeablePayPal,
  verifyPayPalWebhookSignature,
  type PayPalVaultedOrder,
} from "../lib/paypal.ts";

type RecordedCall = { url: string; method?: string; headers: Record<string, string>; body: unknown };

function headerRecord(h: HeadersInit | undefined): Record<string, string> {
  if (!h) return {};
  if (h instanceof Headers) return Object.fromEntries(h.entries());
  if (Array.isArray(h)) return Object.fromEntries(h);
  return { ...(h as Record<string, string>) };
}

/** Installs a mocked global.fetch and returns it plus the call log. Caller restores. */
function mockFetch(router: (call: RecordedCall) => { status: number; body: unknown }) {
  const calls: RecordedCall[] = [];
  const original = globalThis.fetch;
  globalThis.fetch = (async (input: string | URL | Request, init: RequestInit = {}) => {
    const url = typeof input === "string" ? input : input.toString();
    let body: unknown;
    if (typeof init.body === "string") {
      try {
        body = JSON.parse(init.body);
      } catch {
        body = init.body;
      }
    }
    const call: RecordedCall = { url, method: init.method, headers: headerRecord(init.headers), body };
    calls.push(call);
    const { status, body: respBody } = router(call);
    return {
      ok: status >= 200 && status < 300,
      status,
      text: async () => JSON.stringify(respBody),
      json: async () => respBody,
    } as unknown as Response;
  }) as typeof fetch;
  return { calls, restore: () => { globalThis.fetch = original; } };
}

function oauthOk(call: RecordedCall) {
  return call.url.endsWith("/v1/oauth2/token");
}

function setConfigured() {
  process.env.PAYPAL_CLIENT_ID = "test-client-id";
  process.env.PAYPAL_CLIENT_SECRET = "test-client-secret";
}
function clearConfigured() {
  delete process.env.PAYPAL_CLIENT_ID;
  delete process.env.PAYPAL_CLIENT_SECRET;
  delete process.env.PAYPAL_MODE;
  delete process.env.PAYPAL_WEBHOOK_ID;
}

/* ------------------------------------------------------------------ *
 * createPayPalOrder — request shape + the Prefer regression
 * ------------------------------------------------------------------ */

test("createPayPalOrder without vaulting: exact body shape, and requests return=representation", async () => {
  setConfigured();
  const { calls, restore } = mockFetch((call) => {
    if (oauthOk(call)) return { status: 200, body: { access_token: "tok", expires_in: 3600 } };
    return { status: 201, body: { id: "ORDER1", status: "CREATED" } };
  });
  try {
    const order = await createPayPalOrder({
      amountCents: 12345,
      pendingId: "pend_1",
      description: "Nxeon VPS order",
    });
    assert.equal(order.id, "ORDER1");
    const createCall = calls.find((c) => c.url.endsWith("/v2/checkout/orders"));
    assert.ok(createCall, "must POST /v2/checkout/orders");
    // The Prefer-header regression this audit found and fixed.
    assert.equal(createCall!.headers["Prefer"], "return=representation");
    assert.equal(createCall!.headers["PayPal-Request-Id"], "nxeon_pp_create_pend_1");
    const body = createCall!.body as any;
    assert.equal(body.intent, "CAPTURE");
    assert.equal(body.payment_source, undefined, "no vault requested -> no payment_source block at all");
    assert.deepEqual(body.purchase_units, [
      { custom_id: "pend_1", description: "Nxeon VPS order", amount: { currency_code: "USD", value: "123.45" } },
    ]);
  } finally {
    restore();
    clearConfigured();
  }
});

test("createPayPalOrder with vaulting: attributes.vault matches PayPal's Orders v2 schema exactly", async () => {
  setConfigured();
  const { calls, restore } = mockFetch((call) => {
    if (oauthOk(call)) return { status: 200, body: { access_token: "tok", expires_in: 3600 } };
    return { status: 201, body: { id: "ORDER2", status: "CREATED" } };
  });
  try {
    await createPayPalOrder({ amountCents: 999, pendingId: "pend_2", description: "Nxeon game server order", vault: true });
    const createCall = calls.find((c) => c.url.endsWith("/v2/checkout/orders"));
    const body = createCall!.body as any;
    // Field names/nesting/enum values confirmed against PayPal's published
    // OpenAPI spec (vault_paypal_wallet_base): store_in_vault only accepts
    // "ON_SUCCESS"; usage_type is "MERCHANT"|"PLATFORM"; customer_type is a
    // real, documented field ("CONSUMER"|"BUSINESS", default CONSUMER).
    assert.deepEqual(body.payment_source, {
      paypal: {
        attributes: {
          vault: { store_in_vault: "ON_SUCCESS", usage_type: "MERCHANT", customer_type: "CONSUMER" },
        },
      },
    });
  } finally {
    restore();
    clearConfigured();
  }
});

test("createPayPalOrder truncates description to PayPal's 127-char purchase_unit limit", async () => {
  setConfigured();
  const { calls, restore } = mockFetch((call) => {
    if (oauthOk(call)) return { status: 200, body: { access_token: "tok", expires_in: 3600 } };
    return { status: 201, body: { id: "ORDER3", status: "CREATED" } };
  });
  try {
    const longDesc = "x".repeat(200);
    await createPayPalOrder({ amountCents: 100, pendingId: "pend_3", description: longDesc });
    const body = calls.find((c) => c.url.endsWith("/v2/checkout/orders"))!.body as any;
    assert.equal(body.purchase_units[0].description.length, 127);
  } finally {
    restore();
    clearConfigured();
  }
});

test("createPayPalOrder refuses a non-positive amount without ever calling fetch", async () => {
  setConfigured();
  const { calls, restore } = mockFetch(() => ({ status: 200, body: {} }));
  try {
    await assert.rejects(() => createPayPalOrder({ amountCents: 0, pendingId: "p", description: "d" }));
    await assert.rejects(() => createPayPalOrder({ amountCents: -50, pendingId: "p", description: "d" }));
    assert.equal(calls.length, 0, "an invalid amount must never reach the network");
  } finally {
    restore();
    clearConfigured();
  }
});

/* ------------------------------------------------------------------ *
 * capturePayPalOrder — the Prefer regression's other half
 * ------------------------------------------------------------------ */

test("capturePayPalOrder requests return=representation and sends the documented idempotency key", async () => {
  setConfigured();
  const fullOrder: PayPalVaultedOrder = {
    id: "ORDER4",
    status: "COMPLETED",
    purchase_units: [
      { custom_id: "pend_4", amount: { currency_code: "USD", value: "5.00" }, payments: { captures: [{ id: "CAP1", status: "COMPLETED", amount: { currency_code: "USD", value: "5.00" } }] } },
    ],
    payment_source: { paypal: { email_address: "buyer@example.com" } },
  };
  const { calls, restore } = mockFetch((call) => {
    if (oauthOk(call)) return { status: 200, body: { access_token: "tok", expires_in: 3600 } };
    return { status: 200, body: fullOrder };
  });
  try {
    const captured = await capturePayPalOrder("ORDER4");
    const captureCall = calls.find((c) => c.url.endsWith("/v2/checkout/orders/ORDER4/capture"));
    assert.ok(captureCall, "must POST the /capture sub-resource");
    assert.equal(captureCall!.headers["Prefer"], "return=representation");
    assert.equal(captureCall!.headers["PayPal-Request-Id"], "nxeon_pp_capture_ORDER4");
    // Confirms the response the fix makes reachable is actually usable end to end.
    assert.equal(captured.purchase_units?.[0]?.payments?.captures?.[0]?.id, "CAP1");
  } finally {
    restore();
    clearConfigured();
  }
});

/* ------------------------------------------------------------------ *
 * vaultInfoFromCapture / hasChargeablePayPal — pure logic
 * ------------------------------------------------------------------ */

test("vaultInfoFromCapture reads the vault id + payer email only when PayPal actually vaulted it", () => {
  const vaulted: PayPalVaultedOrder = {
    id: "O",
    status: "COMPLETED",
    payment_source: { paypal: { email_address: "a@b.com", attributes: { vault: { id: "VAULT1", status: "VAULTED" } } } },
  };
  assert.deepEqual(vaultInfoFromCapture(vaulted), { vaultId: "VAULT1", payerEmail: "a@b.com" });

  const notVaulted: PayPalVaultedOrder = { id: "O", status: "COMPLETED", payment_source: { paypal: { email_address: "a@b.com" } } };
  assert.equal(vaultInfoFromCapture(notVaulted), null);

  const noPaymentSource: PayPalVaultedOrder = { id: "O", status: "COMPLETED" };
  assert.equal(vaultInfoFromCapture(noPaymentSource), null);
});

test("hasChargeablePayPal requires both PayPal configuration AND a saved vault id", () => {
  clearConfigured();
  assert.equal(hasChargeablePayPal({ paypalVaultId: "V1" }), false, "not configured -> never chargeable, even with a vault id");
  setConfigured();
  assert.equal(hasChargeablePayPal({ paypalVaultId: null }), false, "configured but no vault id -> not chargeable");
  assert.equal(hasChargeablePayPal({ paypalVaultId: "V1" }), true);
  clearConfigured();
});

/* ------------------------------------------------------------------ *
 * chargeVaultedPayPalOffSession — request shape + every outcome branch
 * ------------------------------------------------------------------ */

test("chargeVaultedPayPalOffSession: exact payment_source shape per PayPal's stored_credential schema", async () => {
  setConfigured();
  const { calls, restore } = mockFetch((call) => {
    if (oauthOk(call)) return { status: 200, body: { access_token: "tok", expires_in: 3600 } };
    // COMPLETED immediately — no separate capture call needed.
    return {
      status: 201,
      body: {
        id: "ORDER5",
        status: "COMPLETED",
        purchase_units: [{ payments: { captures: [{ id: "CAP5", status: "COMPLETED", amount: { currency_code: "USD", value: "9.99" } }] } }],
      },
    };
  });
  try {
    const result = await chargeVaultedPayPalOffSession({
      vaultId: "VAULT9",
      amountCents: 999,
      description: "Renewal: 1 month (host1)",
      idempotencyKey: "nxeon_pp_renew_server1_123_a0_999",
    });
    assert.deepEqual(result, { ok: true, captureId: "CAP5", amountCents: 999 });
    const createCall = calls.find((c) => c.url.endsWith("/v2/checkout/orders"));
    assert.equal(createCall!.headers["Prefer"], "return=representation");
    assert.equal(createCall!.headers["PayPal-Request-Id"], "nxeon_pp_renew_server1_123_a0_999_create");
    const body = createCall!.body as any;
    // Field names/enum values confirmed against PayPal's paypal_wallet /
    // paypal_wallet_stored_credential OpenAPI schemas: vault_id is a top-level
    // sibling of stored_credential (NOT nested under attributes); payment_initiator
    // is "CUSTOMER"|"MERCHANT"; usage is "FIRST"|"SUBSEQUENT"|"DERIVED"; usage_pattern
    // shares the same enum as the vault's usage_pattern (RECURRING_POSTPAID valid).
    assert.deepEqual(body.payment_source, {
      paypal: {
        vault_id: "VAULT9",
        stored_credential: {
          payment_initiator: "MERCHANT",
          usage: "SUBSEQUENT",
          usage_pattern: "RECURRING_POSTPAID",
        },
      },
    });
    // No separate /capture call — the order already came back COMPLETED.
    assert.equal(calls.some((c) => c.url.includes("/capture")), false);
  } finally {
    restore();
    clearConfigured();
  }
});

test("chargeVaultedPayPalOffSession: order created non-COMPLETED falls through to an explicit capture", async () => {
  setConfigured();
  const { calls, restore } = mockFetch((call) => {
    if (oauthOk(call)) return { status: 200, body: { access_token: "tok", expires_in: 3600 } };
    if (call.url.endsWith("/v2/checkout/orders")) return { status: 201, body: { id: "ORDER6", status: "CREATED" } };
    if (call.url.endsWith("/v2/checkout/orders/ORDER6/capture")) {
      return {
        status: 200,
        body: { id: "ORDER6", status: "COMPLETED", purchase_units: [{ payments: { captures: [{ id: "CAP6", status: "COMPLETED", amount: { currency_code: "USD", value: "5.00" } }] } }] },
      };
    }
    throw new Error("unexpected call " + call.url);
  });
  try {
    const result = await chargeVaultedPayPalOffSession({
      vaultId: "VAULT9",
      amountCents: 500,
      description: "Renewal",
      idempotencyKey: "key1",
    });
    assert.deepEqual(result, { ok: true, captureId: "CAP6", amountCents: 500 });
    assert.ok(calls.some((c) => c.url.endsWith("/v2/checkout/orders/ORDER6/capture")), "must fall through to an explicit capture");
  } finally {
    restore();
    clearConfigured();
  }
});

test("chargeVaultedPayPalOffSession: a non-COMPLETED final status is a genuine decline, not a crash", async () => {
  setConfigured();
  const { restore } = mockFetch((call) => {
    if (oauthOk(call)) return { status: 200, body: { access_token: "tok", expires_in: 3600 } };
    return { status: 201, body: { id: "ORDER7", status: "VOIDED" } };
  });
  try {
    const result = await chargeVaultedPayPalOffSession({ vaultId: "V", amountCents: 100, description: "d", idempotencyKey: "k" });
    assert.equal(result.ok, false);
    if (!result.ok) assert.equal(result.kind, "declined");
  } finally {
    restore();
    clearConfigured();
  }
});

test("chargeVaultedPayPalOffSession: a network/API failure is caught as transient, never thrown", async () => {
  setConfigured();
  const original = globalThis.fetch;
  globalThis.fetch = (async () => {
    throw new Error("ECONNRESET");
  }) as typeof fetch;
  try {
    const result = await chargeVaultedPayPalOffSession({ vaultId: "V", amountCents: 100, description: "d", idempotencyKey: "k" });
    assert.equal(result.ok, false);
    if (!result.ok) assert.equal(result.kind, "transient");
  } finally {
    globalThis.fetch = original;
    clearConfigured();
  }
});

test("chargeVaultedPayPalOffSession: bad inputs are refused as unavailable without any network call", async () => {
  setConfigured();
  const { calls, restore } = mockFetch(() => ({ status: 200, body: {} }));
  try {
    const noVault = await chargeVaultedPayPalOffSession({ vaultId: "", amountCents: 100, description: "d", idempotencyKey: "k" });
    assert.deepEqual(noVault, { ok: false, kind: "unavailable", message: "No saved PayPal method" });
    const badAmount = await chargeVaultedPayPalOffSession({ vaultId: "V", amountCents: 0, description: "d", idempotencyKey: "k" });
    assert.equal(badAmount.ok, false);
    if (!badAmount.ok) assert.equal(badAmount.kind, "unavailable");
    assert.equal(calls.length, 0, "unavailable outcomes must never reach the network");
  } finally {
    restore();
    clearConfigured();
  }
  clearConfigured();
  const { calls: calls2, restore: restore2 } = mockFetch(() => ({ status: 200, body: {} }));
  try {
    const notConfigured = await chargeVaultedPayPalOffSession({ vaultId: "V", amountCents: 100, description: "d", idempotencyKey: "k" });
    assert.deepEqual(notConfigured, { ok: false, kind: "unavailable", message: "PayPal is not configured" });
    assert.equal(calls2.length, 0);
  } finally {
    restore2();
  }
});

/* ------------------------------------------------------------------ *
 * verifyPayPalWebhookSignature — the exact request PayPal's
 * /v1/notifications/verify-webhook-signature endpoint documents
 * ------------------------------------------------------------------ */

test("verifyPayPalWebhookSignature sends every documented field, read from the documented headers", async () => {
  setConfigured();
  process.env.PAYPAL_WEBHOOK_ID = "WH-123";
  const { calls, restore } = mockFetch((call) => {
    if (oauthOk(call)) return { status: 200, body: { access_token: "tok", expires_in: 3600 } };
    return { status: 200, body: { verification_status: "SUCCESS" } };
  });
  try {
    const headers = new Headers({
      "paypal-auth-algo": "SHA256withRSA",
      "paypal-cert-url": "https://api.paypal.com/cert",
      "paypal-transmission-id": "TXN1",
      "paypal-transmission-sig": "SIGDATA",
      "paypal-transmission-time": "2026-08-29T00:00:00Z",
    });
    const raw = JSON.stringify({ event_type: "PAYMENT.CAPTURE.COMPLETED" });
    const ok = await verifyPayPalWebhookSignature(headers, raw);
    assert.equal(ok, true);
    const verifyCall = calls.find((c) => c.url.endsWith("/v1/notifications/verify-webhook-signature"));
    assert.ok(verifyCall);
    assert.deepEqual(verifyCall!.body, {
      auth_algo: "SHA256withRSA",
      cert_url: "https://api.paypal.com/cert",
      transmission_id: "TXN1",
      transmission_sig: "SIGDATA",
      transmission_time: "2026-08-29T00:00:00Z",
      webhook_id: "WH-123",
      webhook_event: { event_type: "PAYMENT.CAPTURE.COMPLETED" },
    });
  } finally {
    restore();
    clearConfigured();
  }
});

test("verifyPayPalWebhookSignature returns false (never throws) when PayPal reports FAILURE", async () => {
  setConfigured();
  process.env.PAYPAL_WEBHOOK_ID = "WH-123";
  const { restore } = mockFetch((call) => {
    if (oauthOk(call)) return { status: 200, body: { access_token: "tok", expires_in: 3600 } };
    return { status: 200, body: { verification_status: "FAILURE" } };
  });
  try {
    const ok = await verifyPayPalWebhookSignature(new Headers(), "{}");
    assert.equal(ok, false);
  } finally {
    restore();
    clearConfigured();
  }
});

test("verifyPayPalWebhookSignature returns false (never throws) when the verify call itself fails", async () => {
  setConfigured();
  process.env.PAYPAL_WEBHOOK_ID = "WH-123";
  const original = globalThis.fetch;
  globalThis.fetch = (async () => {
    throw new Error("network down");
  }) as typeof fetch;
  try {
    const ok = await verifyPayPalWebhookSignature(new Headers(), "{}");
    assert.equal(ok, false);
  } finally {
    globalThis.fetch = original;
    clearConfigured();
  }
});

